export const topics: LectureTopic[] = topicSeeds.map((seed) => ({
  id: seed.id,
  courseId: course.id,
  semester: seed.semester,
  lectureHours: 0,
  laboratoryHours: 0,
  competencies: [],
  labNumbers: seed.labNumber ? [seed.labNumber] : [],
  sourceTitle: seed.sourceTitle,
  sourceContent: seed.sourceContent,
  displayTitle: seed.displayTitle,
  sourceIds: ['rpd-itpsis-text', ...(seed.labNumber ? [`lab-s${seed.semester}-${String(seed.labNumber).padStart(2, '0')}`] : [])],
  introduction: seed.introduction,
  caseRole: seed.caseRole,
  objective: seed.objective,
  caseBrief: seed.caseBrief,
  diagnostic: seed.diagnostic,
  projectArtifact: seed.projectArtifact,
  nextStep: seed.nextStep,
  codeLabel: seed.codeLabel,
  codeSample: seed.codeSample,
  questions: qs(seed.questions),
}))

export const validateCourseData = () => {
  if (topics.length !== 15 || topics.filter((topic) => topic.semester === 7).length !== 10 || topics.filter((topic) => topic.semester === 8).length !== 5) return false
  if (laboratories.length !== 12 || semesterWorkloads.length !== 2) return false
  if (topics.some((topic) => topic.questions.length !== 8 || topic.courseId !== course.id)) return false
  if (topics.some((topic) => topic.lectureHours !== 0 || topic.laboratoryHours !== 0 || topic.competencies.length !== 0)) return false
  if (semesterWorkloads.some((item) => item.lectureHours !== 0 || item.laboratoryHours !== 0 || item.selfStudyHours !== 0 || item.totalHours !== 0)) return false
  return laboratories.every((lab) => topics.some((topic) => topic.id === lab.topicId && topic.labNumbers.includes(lab.number)))
}
